import {
  ArrowRight,
  ChevronLeft,
  ChevronRight,
  LoaderCircle,
  Search,
  X,
} from "lucide-react";

function SymbolSearch({
  repositoryId,
  parsed,
  disabled,
  select,
}: {
  repositoryId: number;
  parsed: boolean;
  disabled: boolean;
  select: (hit: SearchHit, commitSha: string) => void;
})

type MotionNode = {
  id: number; path: string; x: number; y: number; opacity: number;
  center: boolean; relation: string;
};

type Repository = {
  id: number;
  owner: string;
  name: string;
  github_url: string;
  status: "registered" | "ingested" | "parsed";
  created_at: string;
};

type Overview = {
  languages?: Record<string, number>;
  repository: Repository;
  snapshot: null | {
    commit_sha: string;
    default_branch: string;
    file_count: number;
    line_count: number;
    skipped_files: number;
    ingested_at: string;
  };
  parsing: null | {
    symbol_count: number;
    functions: number;
    methods: number;
    classes: number;
    imports: number;
    parse_error_files: number;
    parsed_at: string;
  };
};

type SourceFile = {
  id: number;
  path: string;
  language: string;
  line_count: number;
  content_hash: string;
};

type SymbolRecord = {
  id: number;
  file_id: number;
  name: string;
  qualified_name: string;
  signature: string;
  symbol_type: string;
  start_line: number;
  end_line: number;
};

type FileDetail = {
  file: SourceFile;
  source: string;
  commit_sha: string;
  github_url: string;
  parsing: null | { has_parse_errors: boolean; symbol_count: number };
  symbols: {
    items: SymbolRecord[];
    total: number | null;
    limit: number;
    offset: number;
  };
};

type IndexChanges = {
  added: number;
  changed: number;
  removed: number;
  unchanged: number;
  parsed_files: number | null;
  reused_files: number | null;
};

type IndexJob = {
  id: string;
  repository_id: number;
  status: "queued" | "running" | "succeeded" | "failed" | "interrupted";
  stage: "queued" | "ingesting" | "parsing" | "complete";
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
  error: string | null;
  commit_sha: string | null;
  changes?: IndexChanges | null;
};

type SearchHit = {
  symbol: SymbolRecord;
  path: string;
  has_parse_errors: boolean;
};

type SemanticHit = {
  document_id: number; score: number; path: string; file_id: number;
  symbol: SymbolRecord | null; title: string; start_line: number; end_line: number;
  excerpt: string; truncated: boolean; github_url: string;
};

type CitedAnswer = {
  question: string; commit_sha: string; answer: string; mode: "source_findings" | "generated"; notice: string | null;
  citations: {id: number; title: string; path: string; file_id: number; symbol: SymbolRecord | null;
    start_line: number; end_line: number; github_url: string; quote: string; quote_truncated: boolean}[];
};

type ImpactReport = {
  commit_sha: string; affected_file_count: number; affected_symbol_count: number; scope: string;
  scope_rule: string; truncated: boolean; unresolved_imports: number; unresolved_calls: number;
  files: {file_id: number; path: string; depth: number; is_test: boolean}[];
  symbols: {symbol: SymbolRecord; path: string; depth: number}[]; limitations: string[];
};

type ArchitectureReport = {
  commit_sha: string; file_count: number; dependency_pairs: number; isolated_files: number;
  cycle_component_count: number; cyclic_files: number; unresolved_imports: number; parse_error_files: number;
  hubs: ArchitectureFile[]; hotspots: ArchitectureFile[]; hotspot_rule: string;
  cycles: {files: {file_id: number; path: string}[]; size: number; truncated: boolean}[];
  cycles_truncated: boolean; limitations: string[];
};

type PullRequestReport = {
  id: string; repository_id: number; number: number; status: "queued" | "running" | "succeeded" | "failed" | "interrupted";
  created_at: string; finished_at: string | null; error: string | null;
  result: null | {title: string; number: number; github_url: string; base_sha: string; head_sha: string;
    commit_sha: string | null; comparable: boolean; requires_base_index: boolean; changed_file_count: number;
    changed_symbol_count: number; symbols_truncated: boolean; impact: ImpactReport | null;
    files: {path: string; status: string; additions: number; deletions: number; supported: boolean;
      indexed: boolean; patch_available: boolean; changed_symbol_ids: number[]}[]; limitations: string[]};
};

type SearchPage = {
  repository_id: number;
  query: string;
  parsed: boolean;
  commit_sha: string | null;
  items: SearchHit[];
  total: number;
  limit: number;
  offset: number;
};

type SymbolDetail = {
  symbol: SymbolRecord;
  file: SourceFile;
  source: string;
  commit_sha: string;
  github_url: string;
  has_parse_errors: boolean;
};

type SourceSelection = {
  symbol: SymbolRecord;
  commit_sha: string;
  request: number;
};

type RelationshipPage = {
  ready: boolean;
  commit_sha: string | null;
  total: number;
  offset: number;
  limit: number;
  items: {
    id: number;
    kind: string;
    resolution: string;
    source_name: string;
    target_name: string;
    file_id: number;
    path: string;
    start_line: number;
    target_file_id: number | null;
    target_path: string | null;
  }[];
};

type DependencyGraph = {
  file_id: number;
  ready: boolean;
  commit_sha: string | null;
  total_neighbors: number;
  unresolved_imports: number;
  self_imports: number;
  nodes: { id: number; path: string }[];
  edges: { source: number; target: number; count: number }[];
};

type CallPage = {
  file_id: number;
  ready: boolean;
  commit_sha: string | null;
  has_parse_errors: boolean;
  summary: { total: number; candidates: number; ambiguous: number; unresolved: number };
  items: { id: number; expression: string; call_type: string; start_line: number;
    end_line: number; column: number; resolution: string;
    caller: SymbolRecord | null; target: SymbolRecord | null }[];
  total: number;
  limit: number;
  offset: number;
};

function workspaceAccess(
  authorization: string | null,
  env: Record<string, string | undefined>,
): "allow" | "challenge" | "unconfigured"

function crossSiteMutation(
  method: string,
  origin: string | null,
  requestOrigin: string,
  fetchSite: string | null,
)

